#define DT_DRV_COMPAT hc_sr04

#include <zephyr/drivers/sensor.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/logging/log.h>
#include <math.h>

LOG_MODULE_REGISTER(HC_SR04, CONFIG_SENSOR_LOG_LEVEL);

/* Driver config */
struct hcsr04_config {
	struct gpio_dt_spec trigger_gpio;
	struct gpio_dt_spec echo_gpio;
};

/* Driver data */
struct hcsr04_data {
	const struct device *dev; /* Pointer to the sensor device */
	struct k_sem trigger_sem;
	struct gpio_callback echo_cb;
	uint64_t echo_start_time;
	uint64_t echo_end_time;
	uint32_t echo_duration_us; /* Last measured echo duration in microseconds */
};

static void hcsr04_echo_gpio_callback(const struct device *port,
					struct gpio_callback *cb,
					gpio_port_pins_t pins)
{
	struct hcsr04_data *data = CONTAINER_OF(cb, struct hcsr04_data, echo_cb);
	const struct hcsr04_config *config = data->dev->config;

	if ((pins & BIT(config->echo_gpio.pin)) == 0) {
		/* Not the pin we are interested in */
		return;
	}

	uint32_t pin_state = gpio_pin_get_raw(port, config->echo_gpio.pin);

	if (pin_state == 1) { /* Rising edge */
		data->echo_start_time = k_cycle_get_64();
	} else { /* Falling edge */
		data->echo_end_time = k_cycle_get_64();
		uint64_t cycles = data->echo_end_time - data->echo_start_time;
		data->echo_duration_us = k_cyc_to_us_floor64(cycles);
		k_sem_give(&data->trigger_sem);
	}
}

static int hcsr04_sample_fetch(const struct device *dev, enum sensor_channel chan)
{
	struct hcsr04_data *data = dev->data;
	const struct hcsr04_config *config = dev->config;
	int ret;

	if (chan != SENSOR_CHAN_ALL && chan != SENSOR_CHAN_DISTANCE) {
		return -ENOTSUP;
	}

	/* Reset semaphore before triggering */
	k_sem_reset(&data->trigger_sem);

	/* Trigger pulse */
	ret = gpio_pin_set_dt(&config->trigger_gpio, 1);
	if (ret < 0) {
		LOG_ERR("Failed to set trigger GPIO high: %d", ret);
		return ret;
	}
	k_busy_wait(10); /* 10us pulse */
	ret = gpio_pin_set_dt(&config->trigger_gpio, 0);
	if (ret < 0) {
		LOG_ERR("Failed to set trigger GPIO low: %d", ret);
		return ret;
	}

	/* Wait for echo pulse to complete (max 38ms for 4m range, 2*4m / 343m/s = 0.023s) */
	/* Use a slightly longer timeout, e.g., 60ms */
	ret = k_sem_take(&data->trigger_sem, K_MSEC(60));
	if (ret < 0) {
		/* Timeout or error */
		LOG_ERR("HC-SR04 echo timeout or error: %d", ret);
		return -EIO; /* Indicate I/O error or timeout */
	}

	return 0;
}

static int hcsr04_channel_get(const struct device *dev, enum sensor_channel chan,
				  struct sensor_value *val)
{
	struct hcsr04_data *data = dev->data;

	if (chan != SENSOR_CHAN_DISTANCE) {
		return -ENOTSUP;
	}

	/* Calculate distance from echo_duration_us
	 * Speed of sound in air is approx 343 m/s.
	 * Distance = (duration * speed_of_sound) / 2
	 * Speed of sound = 34300 cm/s = 0.0343 cm/us
	 * Distance (cm) = (duration_us * 0.0343) / 2
	 * Distance (cm) = duration_us / 58.2
	 * For simplicity, using 58.0 as in many examples.
	 */
	double distance_cm = (double)data->echo_duration_us / 58.0;
	double distance_m = distance_cm / 100.0;

	val->val1 = (int32_t)floor(distance_m);
	val->val2 = (int32_t)((distance_m - val->val1) * 1000000.0);

	return 0;
}

static const struct sensor_driver_api hcsr04_api = {
	.sample_fetch = hcsr04_sample_fetch,
	.channel_get = hcsr04_channel_get,
};

static int hcsr04_init(const struct device *dev)
{
	struct hcsr04_data *data = dev->data;
	const struct hcsr04_config *config = dev->config;
	int ret;

	data->dev = dev; /* Store device pointer in data */

	if (!gpio_is_ready_dt(&config->trigger_gpio)) {
		LOG_ERR("Trigger GPIO device not ready");
		return -ENODEV;
	}

	if (!gpio_is_ready_dt(&config->echo_gpio)) {
		LOG_ERR("Echo GPIO device not ready");
		return -ENODEV;
	}

	ret = gpio_pin_configure_dt(&config->trigger_gpio, GPIO_OUTPUT_INACTIVE);
	if (ret < 0) {
		LOG_ERR("Failed to configure trigger GPIO: %d", ret);
		return ret;
	}

	ret = gpio_pin_configure_dt(&config->echo_gpio, GPIO_INPUT | GPIO_INT_EDGE_BOTH);
	if (ret < 0) {
		LOG_ERR("Failed to configure echo GPIO: %d", ret);
		return ret;
	}

	ret = gpio_pin_interrupt_configure_dt(&config->echo_gpio, GPIO_INT_EDGE_BOTH);
	if (ret < 0) {
		LOG_ERR("Failed to configure echo GPIO interrupt: %d", ret);
		return ret;
	}

	gpio_init_callback(&data->echo_cb, hcsr04_echo_gpio_callback, BIT(config->echo_gpio.pin));
	ret = gpio_add_callback(config->echo_gpio.port, &data->echo_cb);
	if (ret < 0) {
		LOG_ERR("Failed to add echo GPIO callback: %d", ret);
		return ret;
	}

	k_sem_init(&data->trigger_sem, 0, 1); /* Initial count 0, max count 1 */

	return 0;
}

